import { createContext, useContext, useState, useEffect, type ReactNode, useCallback, useMemo } from 'react';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { translations, defaultLanguage, type Language } from './translations';

interface I18nContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: (key: string) => string;
  adminLanguage: Language;
  setAdminLanguage: (lang: Language) => void;
  adminT: (key: string) => string;
}

const I18nContext = createContext<I18nContextType>({
  language: defaultLanguage,
  setLanguage: () => {},
  t: (key: string) => key,
  adminLanguage: 'zh',
  setAdminLanguage: () => {},
  adminT: (key: string) => key,
});

const STORAGE_KEY = '__app_ledlight_language';
const ADMIN_STORAGE_KEY = '__app_ledlight_admin_language';

/**
 * 同步读取保存的语言偏好（首帧就用正确语言渲染，避免闪烁）
 *
 * 🔴 闪烁根因：原来用 useEffect 在 mount 后才读 localStorage，
 * 首帧用 defaultLanguage（英文）渲染，第二帧 setState 切到用户实际语言，
 * 整页文案重新渲染，用户感知为「页面一闪」。
 * 改成 lazy initializer 同步读取，首帧就是正确语言。
 */
function getInitialLanguage(): Language {
  try {
    const saved = scopedStorage.getItem(STORAGE_KEY);
    if (saved && ['en', 'zh', 'es', 'ja'].includes(saved)) {
      return saved as Language;
    }
  } catch {
    // ignore
  }
  return defaultLanguage;
}

function getInitialAdminLanguage(): Language {
  try {
    const saved = scopedStorage.getItem(ADMIN_STORAGE_KEY);
    if (saved && ['en', 'zh', 'es', 'ja'].includes(saved)) {
      return saved as Language;
    }
  } catch {
    // ignore
  }
  return 'zh';
}

export function I18nProvider({ children }: { children: ReactNode }) {
  // 同步初始化，首帧就是正确语言，无闪烁
  const [language, setLanguageState] = useState<Language>(() => getInitialLanguage());
  const [adminLanguage, setAdminLanguageState] = useState<Language>(() => getInitialAdminLanguage());

  // 同步设置 html lang 属性（mount 后一次性设置，不触发重渲染）
  useEffect(() => {
    document.documentElement.lang = language === 'zh' ? 'zh-CN' : language;
  }, [language]);

  const setLanguage = useCallback((lang: Language) => {
    setLanguageState(lang);
    try {
      scopedStorage.setItem(STORAGE_KEY, lang);
    } catch {
      // ignore
    }
    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : lang;
  }, []);

  const setAdminLanguage = useCallback((lang: Language) => {
    setAdminLanguageState(lang);
    try {
      scopedStorage.setItem(ADMIN_STORAGE_KEY, lang);
    } catch {
      // ignore
    }
  }, []);

  function resolveKey(lang: Language, key: string): string | null {
    const keys = key.split('.');
    let value: string | Record<string, unknown> = translations[lang] as Record<string, unknown>;
    for (const k of keys) {
      if (value && typeof value === 'object' && k in value) {
        value = (value as Record<string, unknown>)[k] as string | Record<string, unknown>;
      } else {
        return null;
      }
    }
    return typeof value === 'string' ? value : null;
  }

  const t = useCallback(
    (key: string): string => {
      const result = resolveKey(language, key);
      if (result !== null) return result;
      if (language !== 'en') {
        const fallback = resolveKey('en', key);
        if (fallback !== null) return fallback;
      }
      return key;
    },
    [language]
  );

  const adminT = useCallback(
    (key: string): string => {
      const result = resolveKey(adminLanguage, key);
      if (result !== null) return result;
      if (adminLanguage !== 'zh') {
        const zhFallback = resolveKey('zh', key);
        if (zhFallback !== null) return zhFallback;
      }
      if (adminLanguage !== 'en') {
        const enFallback = resolveKey('en', key);
        if (enFallback !== null) return enFallback;
      }
      return key;
    },
    [adminLanguage]
  );

  // 🔴 用 useMemo 缓存 value，避免每次渲染新建对象导致所有消费者级联重渲染
  const value = useMemo<I18nContextType>(
    () => ({ language, setLanguage, t, adminLanguage, setAdminLanguage, adminT }),
    [language, setLanguage, t, adminLanguage, setAdminLanguage, adminT]
  );

  return (
    <I18nContext.Provider value={value}>
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  return useContext(I18nContext);
}
